# Generated by build.py from recipe.yml for recipe s3-list-a-bucket. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'store/photos', 'store/photos/2025', 'store/photos/2026', 'nolist/photos', 'open/photos', 'open/photos/2026' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'store/photos/readme.txt'), "read me`n")
[IO.File]::WriteAllText((Join-Path $PWD 'store/photos/2025/dec.jpg'), "december`n")
[IO.File]::WriteAllText((Join-Path $PWD 'store/photos/2026/jan.jpg'), "january`n")
[IO.File]::WriteAllText((Join-Path $PWD 'store/photos/2026/feb.jpg'), "february`n")
[IO.File]::WriteAllText((Join-Path $PWD 'nolist/photos/readme.txt'), "no listing here`n")
[IO.File]::WriteAllText((Join-Path $PWD 'open/photos/readme.txt'), "open to anyone`n")
[IO.File]::WriteAllText((Join-Path $PWD 'open/photos/2026/jan.jpg'), "january`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1,DNS:*.s3.us-east-1.amazonaws.com"'
$server0 = Start-Process surl -ArgumentList '--directory', 'store', '--cert', 'server.pem', '--key', 'server.key', '--user', 'AKIAIOSFODNN7EXAMPLE:s3cret', '--list-directories', 's3://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS --cacert server.pem --connect-to ::127.0.0.1:8080 -u AKIAIOSFODNN7EXAMPLE:s3cret s3://photos/2026/ } finally { Stop-Process $server0 }
